recibos.query:
query referencia($startDate: BaseDate, $endDate: BaseDate) {
  alerts(startDate: $startDate, endDate: $endDate, page: 1, limit: 5000,
         dateType: DetectedAt, sortField: ALERT_CODE, sortDirection: ASC) {
    metadata { currentPage totalCount totalPages }
    collection {
      alertCode areaHa detectedAt publishedAt statusName sources
      coordenates { latitude longitude }
      geometryWkt
    }
  }
}

query alerts(
  $page: Int, $limit: Int,
  $startDate: BaseDate, $endDate: BaseDate, $dateType: DateTypes,
  $sources: [SourceTypes!],
  $boundingBox: [Float!],
  $territoryIds: [Int!],
  $sortField: AlertSortField, $sortDirection: SortDirection
) {
  alerts(
    page: $page, limit: $limit,
    startDate: $startDate, endDate: $endDate, dateType: $dateType,
    sources: $sources,
    boundingBox: $boundingBox,
    territoryIds: $territoryIds,
    sortField: $sortField, sortDirection: $sortDirection
  ) {
    collection {
      alertCode
      areaHa
      detectedAt
      publishedAt
      statusName
      sources
      coordenates { latitude longitude }
      geometryWkt
    }
    metadata {
      currentPage
      totalCount
      totalPages
    }
  }
}

